# openEMS model generated by OpenBoard (RF PCB). Requires openEMS + CSXCAD Python bindings.
import os, numpy as np
from CSXCAD import ContinuousStructure
from openEMS import openEMS
from openEMS.physical_constants import C0
unit = 1e-3; f_max = 10e9; f0 = f_max / 2; fc = f_max / 2
FDTD = openEMS(NrTS=60000, EndCriteria=1e-4)
FDTD.SetGaussExcite(f0, fc)
FDTD.SetBoundaryCond(['PML_8'] * 6)
CSX = ContinuousStructure()
FDTD.SetCSX(CSX)
mesh = CSX.GetGrid(); mesh.SetDeltaUnit(unit)
metal = CSX.AddMetal("copper")
sub0 = CSX.AddMaterial("diel0", epsilon=4.4, kappa=2.4478e-2)
sub0.AddBox([-2.6, 0, 0.035], [180.15, 89.3, 1.565], priority=0)
metal.AddLinPoly(points=np.array([[2.6, 177.15, 177.15, 2.6], [43.15, 43.15, 46.15, 46.15]]), norm_dir='z', elevation=1.565, length=0.035, priority=10)  # 0
metal.AddLinPoly(points=np.array([[0.4, 6, 6, 177.15, 177.15, 6, 6, 0.4], [40.65, 40.65, 43.15, 43.15, 46.15, 46.15, 48.65, 48.65]]), norm_dir='z', elevation=0, length=0.035, priority=10)  # 1
